CREATE TABLE public.biz_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),department_id uuid NOT NULL REFERENCES public.biz_departments(id),department_name text NOT NULL,kind text NOT NULL CHECK(kind IN ('plan','report')),period_kind text NOT NULL CHECK(period_kind IN ('month','quarter','year')),year int NOT NULL CHECK(year BETWEEN 2000 AND 2200),period int NOT NULL,deadline timestamptz,deadline_frozen boolean NOT NULL DEFAULT false,first_submitted_at timestamptz,last_submitted_at timestamptz,official_version_id uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,kind,period_kind,year,period),CHECK(period BETWEEN 1 AND (CASE period_kind WHEN 'month' THEN 12 WHEN 'quarter' THEN 4 ELSE 1 END)));
GRANT SELECT ON public.biz_documents TO authenticated; GRANT ALL ON public.biz_documents TO service_role; ALTER TABLE public.biz_documents ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.biz_document_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES public.biz_documents(id),version int NOT NULL,revision int NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','changes','approved')),url text,notes text,reason text,target_version_id uuid REFERENCES public.biz_goal_versions(id),items jsonb NOT NULL DEFAULT '[]',submitted_at timestamptz,approved_at timestamptz,approved_by uuid REFERENCES public.profiles(id),review_comment text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(document_id,version));
GRANT SELECT ON public.biz_document_versions TO authenticated; GRANT ALL ON public.biz_document_versions TO service_role; ALTER TABLE public.biz_document_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.biz_documents ADD CONSTRAINT biz_document_official FOREIGN KEY(official_version_id) REFERENCES public.biz_document_versions(id);
CREATE UNIQUE INDEX biz_document_one_open ON public.biz_document_versions(document_id) WHERE status<>'approved';
CREATE TABLE public.biz_document_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES public.biz_documents(id),version_id uuid NOT NULL REFERENCES public.biz_document_versions(id),actor_id uuid NOT NULL REFERENCES public.profiles(id),action text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.biz_document_events TO authenticated; GRANT ALL ON public.biz_document_events TO service_role; ALTER TABLE public.biz_document_events ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.biz_period_start(_year int,_kind text,_period int) RETURNS timestamptz LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ BEGIN IF _year NOT BETWEEN 2000 AND 2200 OR _kind NOT IN ('month','quarter','year') OR _period NOT BETWEEN 1 AND (CASE _kind WHEN 'month' THEN 12 WHEN 'quarter' THEN 4 ELSE 1 END) THEN RAISE EXCEPTION 'Kỳ không hợp lệ.'; END IF; RETURN make_date(_year,CASE _kind WHEN 'month' THEN _period WHEN 'quarter' THEN (_period-1)*3+1 ELSE 1 END,1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'; END $$;
CREATE FUNCTION public.biz_period_department(_user uuid,_year int,_kind text,_period int) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.department_id FROM public.biz_department_members m WHERE m.user_id=_user AND m.started_at < (((public.biz_period_start(_year,_kind,_period) AT TIME ZONE 'Asia/Ho_Chi_Minh') + make_interval(months=>CASE _kind WHEN 'month' THEN 1 WHEN 'quarter' THEN 3 ELSE 12 END)) AT TIME ZONE 'Asia/Ho_Chi_Minh') AND (m.ended_at IS NULL OR m.ended_at>public.biz_period_start(_year,_kind,_period)) AND (m.ended_at IS NULL OR m.ended_at>m.started_at) ORDER BY m.started_at DESC,m.id DESC LIMIT 1 $$;
CREATE FUNCTION public.biz_doc_access(_user uuid,_dept uuid,_kind text,_review boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN _kind NOT IN ('plan','report') THEN false WHEN _review THEN _user<>auth.uid() AND private.sig_can(auth.uid(),'biz.'||_kind||'_approve') AND (private.sig_can(auth.uid(),'biz.view_all') OR EXISTS(SELECT 1 FROM public.biz_department_members WHERE user_id=auth.uid() AND department_id=_dept AND is_manager AND ended_at IS NULL)) ELSE (_user=auth.uid() AND (private.sig_can(auth.uid(),'biz.view_own') OR private.sig_can(auth.uid(),'biz.'||_kind||'_submit'))) OR private.sig_can(auth.uid(),'biz.view_all') OR EXISTS(SELECT 1 FROM public.biz_department_members WHERE user_id=auth.uid() AND department_id=_dept AND is_manager AND ended_at IS NULL AND (private.sig_can(auth.uid(),'biz.view_dept') OR private.sig_can(auth.uid(),'biz.'||_kind||'_approve'))) END $$;
CREATE FUNCTION public.biz_document_access(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.biz_documents d WHERE d.id=_id AND public.biz_doc_access(d.user_id,d.department_id,d.kind)) $$;
CREATE POLICY biz_docs_scoped ON public.biz_documents FOR SELECT TO authenticated USING(public.biz_document_access(id));
CREATE POLICY biz_doc_versions_scoped ON public.biz_document_versions FOR SELECT TO authenticated USING(public.biz_document_access(document_id));
CREATE POLICY biz_doc_events_scoped ON public.biz_document_events FOR SELECT TO authenticated USING(public.biz_document_access(document_id));
CREATE FUNCTION public.biz_docs_url_ok(_url text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(_url ~ '^https://docs[.]google[.]com/document/d/[A-Za-z0-9_-]+(/(edit|view|preview))?([?][A-Za-z0-9_=&%.-]*)?(#[A-Za-z0-9_=&%.-]*)?$',false) $$;
REVOKE ALL ON FUNCTION public.biz_period_department(uuid,int,text,int),public.biz_doc_access(uuid,uuid,text,boolean),public.biz_document_access(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.biz_doc_access(uuid,uuid,text,boolean),public.biz_document_access(uuid) TO authenticated;